import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l1_p83_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor depthwise_conv2d_kx1_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::optional<torch::Tensor> bias_opt,
    int64_t stride_h,
    int64_t padding_h,
    int64_t dilation_h);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("depthwise_conv2d_kx1_forward", &depthwise_conv2d_kx1_forward,
          "Depthwise (K x 1) convolution forward (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Depthwise (K x 1) convolution kernel using shared memory halo staging.
// Grid: (ceil(W/TW), ceil(H_out/TH), N*C)
// Block: (TW, TH)
// Each block loads a (TH*stride + dilation*(K-1)) x TW input slab into shared memory,
// then each thread accumulates K taps and writes one output element.
	emplate <int TW, int TH>
__global__ void depthwise_kx1_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C, int H, int W,
    int K, int stride, int padding, int dilation,
    int H_out, int W_out)
{
    // which (n, c) slice
    int nc = blockIdx.z;
    int n  = nc / C;
    int c  = nc % C;

    // output tile origin
    int out_w0 = blockIdx.x * TW;
    int out_h0 = blockIdx.y * TH;

    int tx = threadIdx.x;  // width index within tile
    int ty = threadIdx.y;  // height index within tile

    // input slab needed: height = TH*stride + dilation*(K-1)
    int slab_h = TH * stride + dilation * (K - 1);
    int slab_w = TW;

    // shared memory: slab_h rows x slab_w cols
    extern __shared__ float smem[];

    // base input pointer for this (n, c) slice
    const float* in_ptr = input + (n * C + c) * H * W;

    // load shared memory
    int in_hbase = out_h0 * stride - padding;
    int in_w_base = out_w0;

    int total_slab = slab_h * slab_w;
    int tid = ty * TW + tx;
    for (int i = tid; i < total_slab; i += TW * TH) {
        int sh = i / slab_w;
        int sw = i % slab_w;
        int ih = in_h_base + sh;
        int iw = in_w_base + sw;
        float val = 0.0f;
        if (ih >= 0 && ih < H && iw >= 0 && iw < W) {
            val = in_ptr[ih * W + iw];
        }
        smem[sh * slab_w + sw] = val;
    }
    __syncthreads();

    int out_h = out_h0 + ty;
    int out_w = out_w0 + tx;

    if (out_h < H_out && out_w < W_out) {
        // per-channel weights: weight shape [C, 1, K, 1]
        const float* w_ptr = weight + c * K;
        float acc = 0.0f;
        #pragma unroll 8
        for (int k = 0; k < K; ++k) {
            int sh = ty * stride + k * dilation;
            acc += smem[sh * slab_w + tx] * w_ptr[k];
        }
        if (bias) acc += bias[c];
        output[(n * C + c) * H_out * W_out + out_h * W_out + out_w] = acc;
    }

torch::Tensor depthwise_conv2d_kx1_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::optional<torch::Tensor> bias_opt,
    int64_t stride_h,
    int64_t padding_h,
    int64_t dilation_h)
{
    TORCH_CHECK(input.is_cuda() && weight.is_cuda(), "inputs must be CUDA tensors");
    TORCH_CHECK(input.scalar_type() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");

    int N = input.size(0);
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);
    int K = weight.size(2);  // weight shape: [C, 1, K, 1]

    int H_out = (H + 2 * padding_h - dilation_h * (K - 1) - 1) / stride_h + 1;
    int W_out = W;  // kernel width=1, so width dimension unchanged

    auto output = torch::empty({N, C, H_out, W_out}, input.options());

    const float* bias_ptr = nullptr;
    if (bias_opt.has_value() && bias_opt.value().defined()) {
        bias_ptr = bias_opt.value().data_ptr<float>();
    }

    // Tile dimensions
    const int TW = 32;
    const int TH = 8;

    dim3 block(TW, TH);
    dim3 grid(
        (W_out + TW - 1) / TW,
        (H_out + TH - 1) / TH,
        N * C
    );

    int slab_h = TH * stride_h + dilation_h * (K - 1);
    int smem_bytes = slab_h * TW * sizeof(float);

    depthwise_kx1_kernel<TW, TH><<grid, block, smem_bytes>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        N, C, H, W,
        K, (int)stride_h, (int)padding_h, (int)dilation_h,
        H_out, W_out
    );

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Performs a depthwise 2D convolution with a square input and an asymmetric kernel.

        Args:
            in_channels (int): Number of channels in the input tensor.
            kernel_size (int): Size of the convolution kernel.
            stride (int, optional): Stride of the convolution. Defaults to 1.
            padding (int, optional): Padding applied to the input. Defaults to 0.
            dilation (int, optional): Spacing between kernel elements. Defaults to 1.
            bias (bool, optional): If `True`, adds a learnable bias to the output. Defaults to `False`.
        """
    def __init__(self, in_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, bias: bool = False):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.conv2d = nn.Conv2d(in_channels, in_channels, kernel_size=(kernel_size, 1), stride=stride, padding=padding, dilation=dilation, groups=in_channels, bias=bias)
        # <<<END_IMPROVE>>>

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Performs the depthwise 2D convolution.

                Args:
                    x (torch.Tensor): Input tensor of shape (batch_size, in_channels, height, width).

                Returns:
                    torch.Tensor: Output tensor of shape (batch_size, in_channels, height_out, width_out).
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        conv = self.conv2d
        if (
        x.is_cuda and
        x.dtype == torch.float32 and
        x.is_contiguous() and
        conv.groups == conv.in_channels and
        conv.kernel_size[1] == 1 and
        conv.weight.is_contiguous()
        ):
            return _stark_get_extension().depthwise_conv2d_kx1_forward(
            x,
            conv.weight,
            conv.bias,
            conv.stride[0],
            conv.padding[0],
            conv.dilation[0],
            )
        return self.conv2d(x)
        # <<<END_IMPROVE>>>

