# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Shared-memory tiled depthwise Kx1 kernel.
// Each block covers a tile of (TILE_H output rows) x (TILE_W output cols) for one (n,c) slice.
// The input slab loaded into shared memory has shape:
//   (TILE_H * stride + dilation*(K-1)) x TILE_W
// so every tap for every output in the tile is served from shared memory.

template <int TILE_H, int TILE_W, int THREADS>
__global__ void depthwise_kx1_smem_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C, int H, int W,
    int K, int stride, int padding, int dilation,
    int H_out, int W_out)
{
    // Grid: x = tiles over W, y = tiles over H, z = n*C + c
    int nc   = blockIdx.z;
    int n    = nc / C;
    int c    = nc % C;

    int tile_h0 = blockIdx.y * TILE_H;   // first output row this block handles
    int tile_w0 = blockIdx.x * TILE_W;   // first output col this block handles

    // Shared memory slab dimensions
    // slab_h = TILE_H * stride + dilation*(K-1)  rows of input
    // slab_w = TILE_W                             cols of input
    // (for stride>1 we need stride*TILE_H input rows)
    const int slab_h = TILE_H * stride + dilation * (K - 1);
    const int slab_w = TILE_W;

    extern __shared__ float smem[];  // slab_h * slab_w floats

    // Top-left input row/col corresponding to tile_h0, tile_w0
    int h_in0 = tile_h0 * stride - padding;
    int w_in0 = tile_w0 * stride - padding;

    const float* in_base = input + (nc * H) * W;

    // Cooperatively load the input slab
    int slab_size = slab_h * slab_w;
    for (int i = threadIdx.x; i < slab_size; i += THREADS) {
        int sr = i / slab_w;
        int sc = i % slab_w;
        int h_in = h_in0 + sr;
        int w_in = w_in0 + sc;
        float val = 0.0f;
        if (h_in >= 0 && h_in < H && w_in >= 0 && w_in < W) {
            val = in_base[h_in * W + w_in];
        }
        smem[i] = val;
    }
    __syncthreads();

    // Load per-channel weights into registers (K small, reuse across all outputs)
    // We keep them in a local array; compiler will put them in regs for small K
    float w_reg[16];  // K <= 16 assumed
    if (threadIdx.x < K) {
        w_reg[threadIdx.x] = weight[c * K + threadIdx.x];
    }
    // Broadcast via shared memory to all threads
    __shared__ float w_smem[16];
    if (threadIdx.x < K) w_smem[threadIdx.x] = weight[c * K + threadIdx.x];
    __syncthreads();

    float bias_val = (bias != nullptr) ? bias[c] : 0.0f;

    // Each thread computes one output element within the tile
    int total_out = TILE_H * TILE_W;
    for (int i = threadIdx.x; i < total_out; i += THREADS) {
        int th = i / TILE_W;  // local row index in tile
        int tw = i % TILE_W;  // local col index in tile

        int h_out = tile_h0 + th;
        int w_out = tile_w0 + tw;

        if (h_out >= H_out || w_out >= W_out) continue;

        // For this output, the input row base in the slab is th*stride
        // col offset in slab is tw (stride=1 in W since kernel width=1, w_in=w_out*stride-padding)
        // But slab_w == TILE_W, so col index in slab = tw
        int slab_row_base = th * stride;
        float acc = 0.0f;
        #pragma unroll
        for (int k = 0; k < K; ++k) {
            int slab_row = slab_row_base + k * dilation;
            acc += smem[slab_row * slab_w + tw] * w_smem[k];
        }
        acc += bias_val;
        output[((nc * H_out) + h_out) * W_out + w_out] = acc;
    }
}

// Generic fallback kernel (no shared memory, handles all configs)
template <int THREADS>
__global__ void depthwise_kx1_generic_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C, int H, int W,
    int K, int stride, int padding, int dilation,
    int H_out, int W_out)
{
    int idx   = blockIdx.x * THREADS + threadIdx.x;
    int total = N * C * H_out * W_out;
    if (idx >= total) return;

    int w_out = idx % W_out;
    int tmp   = idx / W_out;
    int h_out = tmp % H_out;
    tmp      /= H_out;
    int c     = tmp % C;
    int n     = tmp / C;

    int h_in_base = h_out * stride - padding;
    int w_in      = w_out * stride - padding;

    const float* in_ptr = input  + (n * C + c) * H * W;
    const float* w_ptr  = weight + c * K;

    float acc = 0.0f;
    if (w_in >= 0 && w_in < W) {
        #pragma unroll 4
        for (int k = 0; k < K; ++k) {
            int h_in = h_in_base + k * dilation;
            if (h_in >= 0 && h_in < H) {
                acc += in_ptr[h_in * W + w_in] * w_ptr[k];
            }
        }
    }
    if (bias != nullptr) acc += bias[c];
    output[idx] = acc;
}

